private ContentHandler getFormatHandler() {
    switch(type) {
        case TEXT:
            return new ToTextContentHandler();
        case HTML:
            return new ToHTMLContentHandler();
        case XML:
            return new ToXMLContentHandler();
        case MARKDOWN:
            return new ToMarkdownContentHandler();
        default:
            return new ToTextContentHandler();
    }
}
